create table "public"."ambassador_codes" (
    "id" bigint generated by default as identity not null,
    "profile_id" bigint not null,
    "code" text not null,
    "active" boolean not null default true,
    "tenant_id" text not null,
    "created_at" timestamp with time zone not null default (now() AT TIME ZONE 'utc'::text)
);

alter table "public"."ambassador_codes" enable row level security;

CREATE UNIQUE INDEX ambassador_codes_pkey ON public.ambassador_codes USING btree (id);

CREATE UNIQUE INDEX ambassador_codes_profile_id_tenant_id_key ON public.ambassador_codes USING btree (profile_id, tenant_id);

CREATE UNIQUE INDEX ambassador_codes_code_tenant_id_key ON public.ambassador_codes USING btree (code, tenant_id);

CREATE INDEX idx_ambassador_codes_tenant_id ON public.ambassador_codes USING btree (tenant_id);

alter table "public"."ambassador_codes" add constraint "ambassador_codes_pkey" PRIMARY KEY using index "ambassador_codes_pkey";

alter table "public"."ambassador_codes" add constraint "ambassador_codes_profile_id_tenant_id_key" UNIQUE using index "ambassador_codes_profile_id_tenant_id_key";

alter table "public"."ambassador_codes" add constraint "ambassador_codes_code_tenant_id_key" UNIQUE using index "ambassador_codes_code_tenant_id_key";

alter table "public"."ambassador_codes" add constraint "ambassador_codes_code_upper_check" CHECK ((code = upper(code))) not valid;

alter table "public"."ambassador_codes" validate constraint "ambassador_codes_code_upper_check";

alter table "public"."ambassador_codes" add constraint "ambassador_codes_profile_id_fkey" FOREIGN KEY (profile_id) REFERENCES public.profiles(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;

alter table "public"."ambassador_codes" validate constraint "ambassador_codes_profile_id_fkey";

grant delete on table "public"."ambassador_codes" to "anon";

grant insert on table "public"."ambassador_codes" to "anon";

grant references on table "public"."ambassador_codes" to "anon";

grant select on table "public"."ambassador_codes" to "anon";

grant trigger on table "public"."ambassador_codes" to "anon";

grant truncate on table "public"."ambassador_codes" to "anon";

grant update on table "public"."ambassador_codes" to "anon";

grant delete on table "public"."ambassador_codes" to "authenticated";

grant insert on table "public"."ambassador_codes" to "authenticated";

grant references on table "public"."ambassador_codes" to "authenticated";

grant select on table "public"."ambassador_codes" to "authenticated";

grant trigger on table "public"."ambassador_codes" to "authenticated";

grant truncate on table "public"."ambassador_codes" to "authenticated";

grant update on table "public"."ambassador_codes" to "authenticated";

grant delete on table "public"."ambassador_codes" to "service_role";

grant insert on table "public"."ambassador_codes" to "service_role";

grant references on table "public"."ambassador_codes" to "service_role";

grant select on table "public"."ambassador_codes" to "service_role";

grant trigger on table "public"."ambassador_codes" to "service_role";

grant truncate on table "public"."ambassador_codes" to "service_role";

grant update on table "public"."ambassador_codes" to "service_role";

create policy "tenant_isolation"
on "public"."ambassador_codes"
as permissive
for all
to public
using ((tenant_id = ((( SELECT current_setting('request.headers'::text, true) AS current_setting))::json ->> 'x-tenant-id'::text)));
